 75	export async function getKbContext(workspaceId?: string, text?: string, apiKey?: string) {
 76	  if (!workspaceId || !text || !apiKey) return '';
 77	  try {
 78	    const openai = new OpenAI({ apiKey });
 79	    const cleaned = text.slice(0, 2000);
 80	    const embedding = await openai.embeddings.create({
 81	      model: 'text-embedding-3-small',
 82	      input: cleaned,
 83	    });
 84	    const vectorString = `[${embedding.data[0].embedding.join(',')}]`;
 85	    const rows: UnknownRecord[] = await prisma.$queryRaw`
 86	      SELECT v.content, (v.embedding <=> ${vectorString}::vector) AS distance
 87	      FROM "RAC_Vector" v
 88	      JOIN "RAC_KnowledgeSource" s ON v."sourceId" = s.id
 89	      JOIN "RAC_KnowledgeBase" kb ON s."knowledgeBaseId" = kb.id
 90	      WHERE kb."workspaceId" = ${workspaceId}
 91	      ORDER BY distance ASC
 92	      LIMIT 3
 93	    `;
 94	    if (!rows || rows.length === 0) return '';
 95	    return rows
 96	      .map((r: UnknownRecord) => r.content)
 97	      .join('\n---\n')
 98	      .slice(0, 1500);
 99	  } catch (err: unknown) {
100	    const errInstanceofError =
101	      err instanceof Error ? err : new Error(typeof err === 'string' ? err : 'unknown error');
102	    log.warn('kb_context_error', { error: errInstanceofError.message });
103	    return '';
104	  }
105	}
