162	export function normalizeAutonomyLedgerValue(value: unknown): unknown {
163	  if (value instanceof Date) return value.toISOString();
164	  if (Array.isArray(value)) return value.map((item) => normalizeAutonomyLedgerValue(item));
165	  if (value && typeof value === 'object') {
166	    const record = value as Record<string, unknown>;
167	    return Object.keys(record)
168	      .sort()
169	      .reduce<Record<string, unknown>>((acc, key) => {
170	        acc[key] = normalizeAutonomyLedgerValue(record[key]);
171	        return acc;
172	      }, {});
173	  }
174	  return value ?? null;
175	}
