222	}) {
223	  const client = prisma as never as UnknownRecord;
224	  if (!client.autonomyExecution) return { allowed: true as const, record: null };
225	
226	  try {
227	    const record = await client.autonomyExecution.create({
228	      data: {
229	        workspaceId: input.workspaceId,
230	        contactId: input.contactId,
231	        conversationId: input.conversationId,
232	        workItemId: input.workItemId || null,
233	        proofId: input.proofId || null,
234	        capabilityCode: input.capabilityCode || input.actionType,
235	        tacticCode: input.tacticCode || null,
236	        idempotencyKey: input.idempotencyKey,
237	        actionType: input.actionType,
238	        request: input.request,
239	        status: 'PENDING',
240	      },
241	    });
242	    return { allowed: true as const, record };
243	  } catch (err: unknown) {
244	    if (!isAutonomyExecutionDuplicate(err)) throw err;
245	
246	    const existing = await client.autonomyExecution.findFirst({
247	      where: { workspaceId: input.workspaceId, idempotencyKey: input.idempotencyKey },
248	    });
249	
250	    if (existing?.status === 'FAILED') {
251	      const record = await client.autonomyExecution.update({
252	        where: { id: existing.id },
253	        data: {
254	          request: input.request,
255	          workItemId: input.workItemId || null,
256	          proofId: input.proofId || null,
257	          capabilityCode: input.capabilityCode || input.actionType,
258	          tacticCode: input.tacticCode || null,
259	          response: null,
260	          error: null,
261	          status: 'PENDING',
262	        },
263	      });
264	      return { allowed: true as const, record, replay: true as const };
265	    }
266	
267	    return {
268	      allowed: false as const,
269	      record: existing || null,
270	      reason:
271	        existing?.status === 'SUCCESS'
272	          ? 'duplicate_execution_success'
273	          : 'duplicate_execution_pending',
274	    };
275	  }
276	}
