 78	export async function dispatchAutonomousReplyPlan(input: {
 79	  workspaceId: string;
 80	  phone: string;
 81	  chatId?: string | undefined;
 82	  message: string;
 83	  idempotencyKey: string;
 84	  quotedMessageId?: string | undefined;
 85	  customerMessages?: QuotedCustomerMessage[] | undefined;
 86	  settings?: UnknownRecord | undefined;
 87	  mirrorReplies?: boolean | undefined;
 88	}): Promise<Array<{ quotedMessageId?: string | undefined; text: string }>> {
 89	  const normalizedCustomerMessages = (input.customerMessages || [])
 90	    .map((message) => ({
 91	      content: String(message.content || '').trim(),
 92	      quotedMessageId: String(message.quotedMessageId || '').trim(),
 93	      createdAt: message.createdAt,
 94	    }))
 95	    .filter((message) => message.content && message.quotedMessageId);
 96	
 97	  const replyPlan =
 98	    input.mirrorReplies === true && normalizedCustomerMessages.length > 0
 99	      ? await buildQuotedReplyPlan({
100	          draftReply: input.message,
101	          customerMessages: normalizedCustomerMessages,
102	          settings: input.settings,
103	        })
104	      : [{ quotedMessageId: input.quotedMessageId, text: input.message }];
105	
106	  if (!replyPlan.length) {
107	    replyPlan.push({ quotedMessageId: input.quotedMessageId, text: input.message });
108	  }
109	
110	  await forEachSequential(Array.from(replyPlan.entries()), async ([index, reply]) => {
111	    const effectiveQuotedMessageId = reply.quotedMessageId || input.quotedMessageId;
112	    await dispatchAutonomousTextMessage({
113	      workspaceId: input.workspaceId,
114	      phone: input.phone,
115	      chatId: input.chatId,
116	      message: reply.text,
117	      idempotencyKey: `${input.idempotencyKey}:${index + 1}`,
118	      quotedMessageId: effectiveQuotedMessageId,
119	    });
120	  });
121	
122	  return replyPlan.map((reply) => ({
123	    quotedMessageId: reply.quotedMessageId || input.quotedMessageId,
124	    text: reply.text,
125	  }));
126	}
